import java.util.Scanner;
public class PolyalphabeticCipher {static String transform(String s,String key,boolean decrypt){StringBuilder o=new StringBuilder();int j=0;for(char c:s.toCharArray()){if(c>='A'&&c<='Z'){int k=key.charAt(j++%key.length())-'A';o.append((char)('A'+Math.floorMod(c-'A'+(decrypt?-k:k),26)));}else o.append(c);}return o.toString();}public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter plaintext: ");String p=sc.nextLine().toUpperCase();System.out.print("Enter key: ");String k=sc.nextLine().toUpperCase().replaceAll("[^A-Z]","");if(k.isEmpty()){System.out.println("Key must contain letters.");return;}String c=transform(p,k,false);System.out.println("Ciphertext: "+c);System.out.println("Decrypted: "+transform(c,k,true));}}
